// Package models holds the data types and database access, mostly generated by sqlc.
package models

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
)

// InsertUser creates a pending user and returns false when the email is already taken, whatever its case.
func (q *Queries) InsertUser(ctx context.Context, user CreateUserParams) (bool, error) {
	_, err := q.CreateUser(ctx, user)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("insert user: %w", err)
	}
	return true, nil
}

// FindUserByEmail returns the user with this email, whatever its case, and
// false when there is none.
func (q *Queries) FindUserByEmail(ctx context.Context, email string) (User, bool, error) {
	user, err := q.GetUserByEmail(ctx, email)
	if errors.Is(err, pgx.ErrNoRows) {
		return User{}, false, nil
	}
	if err != nil {
		return User{}, false, fmt.Errorf("find user by email: %w", err)
	}
	return user, true, nil
}
